  1	/**
  2	 * Unit tests for PollingManager.
  3	 *
  4	 * All dependencies (ProjectManager, WorkspaceManager, fetchStatusFn) are
  5	 * replaced with lightweight in-memory mocks so no real git I/O or disk I/O
  6	 * is needed.
  7	 */
  8	import { test } from 'node:test';
  9	import assert from 'node:assert/strict';
 10	import type { ProjectManager } from '../../models/project/project.manager.js';
 11	import type { WorkspaceManager } from '../../models/workspace/workspace.manager.js';
 12	import type { WorkspaceInfo } from '../../models/workspace/workspace.types.js';
 13	import type { GitStatusInfo } from '../../git/git.types.js';
 14	import { PollingManager } from '../pollingManager.js';
 15	import { makeTestConfig } from '../../tests/test-helpers.js';
 16	
 17	// ---------------------------------------------------------------------------
 18	// Minimal stubs / factories
 19	// ---------------------------------------------------------------------------
 20	
 21	const BASE_CONFIG = makeTestConfig('/fake');
 22	
 23	function makeStatus(branch = 'main'): GitStatusInfo {
 24	    return {
 25	        currentBranch: branch,
 26	        localCommits: 0,
 27	        unfetchedCommits: 0,
 28	        modifiedFiles: 0,
 29	        lastActivity: '2024-01-01T00:00:00Z',
 30	        hasConflicts: false,
 31	    };
 32	}
 33	
 34	interface MockProject {
 35	    Id: string;
 36	    Repositories: string[];
 37	    Workspaces: Record<string, unknown>;
 38	    [key: string]: unknown;
 39	}
 40	
 41	function makeProjectManager(projects: MockProject[]): ProjectManager {
 42	    return {
 43	        list: () => projects.map((p) => ({ Id: p.Id, Name: p.Id })),
 44	        getById: (id: string) => projects.find((p) => p.Id === id) ?? undefined,
 45	        updateLastActivity: (_id: string, _value: string) => { /* no-op */ },
 46	    } as unknown as ProjectManager;
 47	}
 48	
 49	function makeWorkspaceManager(workspaces: Record<string, WorkspaceInfo | undefined>): WorkspaceManager {
 50	    return {
 51	        getById: (projectId: string, workspaceId: string): WorkspaceInfo | undefined => {
 52	            return workspaces[`${projectId}:${workspaceId}`];
 53	        },
 54	    } as unknown as WorkspaceManager;
 55	}
 56	
 57	/**
 58	 * Returns a mock WorkspaceManager where every (projectId, workspaceId) combo
 59	 * that has the form `<project>:STABLE` is treated as existing.
 60	 */
 61	function makeDefaultWorkspaceManager(): WorkspaceManager {
 62	    return {
 63	        getById: (projectId: string, workspaceId: string): WorkspaceInfo | undefined => {
 64	            if (workspaceId === 'STABLE') {
 65	                return {
 66	                    ProjectID: projectId,
 67	                    WorkspaceID: 'STABLE',
 68	                    Description: '',
 69	                    DateCreated: '',
 70	                    DateModified: '',
 71	                    Notes: '',
 72	                };
 73	            }
 74	            return undefined;
 75	        },
 76	    } as unknown as WorkspaceManager;
 77	}
 78	
 79	// ---------------------------------------------------------------------------
 80	// Helpers
 81	// ---------------------------------------------------------------------------
 82	
 83	/** Waits for a promise to resolve within `ms` milliseconds. */
 84	function withTimeout<T>(promise: Promise<T>, ms: number): Promise<T> {
 85	    return Promise.race([
 86	        promise,
 87	        new Promise<T>((_, reject) =>
 88	            setTimeout(() => reject(new Error(`Timed out after ${ms}ms`)), ms),
 89	        ),
 90	    ]);
 91	}
 92	
 93	// ---------------------------------------------------------------------------
 94	// getStatus — cache reads
 95	// ---------------------------------------------------------------------------
 96	
 97	test('getStatus: returns null before the first poll', () => {
 98	    const pm = makeProjectManager([]);
 99	    const wm = makeDefaultWorkspaceManager();
100	    const mgr = new PollingManager(BASE_CONFIG, pm, wm);

 1	/**
 2	 * QA tests for WP-006: PollingManager × ErrorLogManager integration.
 3	 *
 4	 * Covers all 6 acceptance criteria:
 5	 *  AC1 – PollingManager accepts an optional ErrorLogManager constructor parameter.
 6	 *  AC2 – A fetch failure produces a warning-severity entry with source 'polling' and operation 'status-poll'.
 7	 *  AC3 – A persistently failing repo produces at most ONE entry per sweep-to-sweep cycle (deduplication).
 8	 *  AC4 – Recovery (successful fetch) removes the path from the dedup set; a subsequent failure is logged again.
 9	 *  AC5 – Log entry Context includes ProjectId, WorkspaceId, RepositoryId from the path.
10	 *  AC6 – Existing tests pass without modification (smoke: no errorLogManager → no log calls).
11	 *
12	 * All dependencies are in-memory mocks; no real git I/O or disk I/O.
13	 */
14	
15	import { test } from 'node:test';
16	import assert from 'node:assert/strict';
17	import type { AppConfig } from '../../config/config.types.js';
18	import type { ProjectManager } from '../../models/project/project.manager.js';
19	import type { WorkspaceManager } from '../../models/workspace/workspace.manager.js';
20	import type { ErrorLogManager } from '../../error-log/error-log.manager.js';
21	import type { ErrorLogEntry } from '../../error-log/error-log.types.js';
22	import type { GitStatusInfo } from '../../git/git.types.js';
23	import { PollingManager } from '../pollingManager.js';
24	import { makeTestConfig } from '../../tests/test-helpers.js';
25	
26	// ---------------------------------------------------------------------------
27	// Shared test fixtures
28	// ---------------------------------------------------------------------------
29	
30	const BASE_CONFIG = makeTestConfig('/fake');
31	
32	function makeStatus(branch = 'main'): GitStatusInfo {
33	    return {
34	        currentBranch: branch,
35	        localCommits: 0,
36	        unfetchedCommits: 0,
37	        modifiedFiles: 0,
38	        lastActivity: '2024-01-01T00:00:00Z',
39	        hasConflicts: false,
40	    };
41	}
42	
43	function makeProjectManager(repos: string[]): ProjectManager {
44	    const project = { Id: 'proj', Repositories: repos, Workspaces: { STABLE: {} } };
45	    return {
46	        list: () => [{ Id: 'proj', Name: 'proj' }],
47	        getById: (id: string) => (id === 'proj' ? project : undefined),
48	        updateLastActivity: (_id: string, _value: string) => { /* no-op */ },
49	    } as unknown as ProjectManager;
50	}
51	
52	function makeWorkspaceManager(): WorkspaceManager {
53	    return {
54	        getById: (projectId: string, workspaceId: string) => {
55	            if (workspaceId === 'STABLE') {
56	                return { ProjectID: projectId, WorkspaceID: 'STABLE', Description: '', DateCreated: '', DateModified: '' };
57	            }
58	            return undefined;
59	        },
60	    } as unknown as WorkspaceManager;
61	}
62	
63	/**
64	 * Creates a lightweight mock of ErrorLogManager that records every `append()` call.
65	 */
66	function makeErrorLogManager(): { mock: ErrorLogManager; calls: Array<Omit<ErrorLogEntry, 'Id' | 'Timestamp'>> } {
67	    const calls: Array<Omit<ErrorLogEntry, 'Id' | 'Timestamp'>> = [];
68	    const mock = {
69	        append(entry: Omit<ErrorLogEntry, 'Id' | 'Timestamp'>): ErrorLogEntry {
70	            calls.push(entry);
71	            return { ...entry, Id: calls.length, Timestamp: new Date().toISOString() };
72	        },
73	    } as unknown as ErrorLogManager;
74	    return { mock, calls };
75	}
76	
77	// ---------------------------------------------------------------------------
78	// AC1 — PollingManager accepts an optional ErrorLogManager constructor parameter
79	// ---------------------------------------------------------------------------
80	
81	test('AC1: PollingManager can be constructed without errorLogManager (backward compat)', () => {
82	    const pm = makeProjectManager([]);
83	    const wm = makeWorkspaceManager();
84	    // Must not throw — 4-arg construction should still work
85	    const mgr = new PollingManager(BASE_CONFIG, pm, wm, async () => makeStatus());
86	    assert.ok(mgr instanceof PollingManager);
87	});
88	
89	test('AC1: PollingManager can be constructed WITH an errorLogManager as the 5th arg', () => {
90	    const pm = makeProjectManager([]);
91	    const wm = makeWorkspaceManager();
92	    const { mock } = makeErrorLogManager();
93	    const mgr = new PollingManager(BASE_CONFIG, pm, wm, async () => makeStatus(), mock);
94	    assert.ok(mgr instanceof PollingManager);
95	});
96	
97	// ---------------------------------------------------------------------------
98	// AC2 — A fetch failure produces a warning-severity entry with source='polling' and operation='status-poll'
99	// ---------------------------------------------------------------------------

101	
102	    assert.strictEqual(mgr.getStatus('/fake/projects/proj/STABLE/repo'), null);
103	});
104	
105	test('getStatus: returns the cached value after refreshWorkspace', async () => {
106	    const project = {
107	        Id: 'proj',
108	        Repositories: ['repo'],
109	        Workspaces: { STABLE: {} },
110	    };
111	    const pm = makeProjectManager([project]);
112	    const wm = makeDefaultWorkspaceManager();
113	    const expectedStatus = makeStatus('feature');
114	    const fetchFn = async (_path: string) => expectedStatus;
115	
116	    const mgr = new PollingManager(BASE_CONFIG, pm, wm, fetchFn);
117	    await mgr.refreshWorkspace('proj', 'STABLE');
118	
119	    const cached = mgr.getStatus('/fake/projects/proj/STABLE/repo');
120	    assert.deepEqual(cached, expectedStatus);
121	});
122	
123	test('getStatus: returns null for a path that has never been polled', async () => {
124	    const project = {
125	        Id: 'proj',
126	        Repositories: ['repo-a'],
127	        Workspaces: { STABLE: {} },
128	    };
129	    const pm = makeProjectManager([project]);
130	    const wm = makeDefaultWorkspaceManager();
131	    const mgr = new PollingManager(BASE_CONFIG, pm, wm, async () => makeStatus());
132	
133	    await mgr.refreshWorkspace('proj', 'STABLE');
134	    // repo-b was never polled
135	    assert.strictEqual(mgr.getStatus('/fake/projects/proj/STABLE/repo-b'), null);
136	});
137	
138	// ---------------------------------------------------------------------------
139	// refreshWorkspace
140	// ---------------------------------------------------------------------------
141	
142	test('refreshWorkspace: fetches status for every repo in the workspace', async () => {
143	    const project = {
144	        Id: 'my-proj',
145	        Repositories: ['repo-1', 'repo-2'],
146	        Workspaces: { STABLE: {} },
147	    };
148	    const pm = makeProjectManager([project]);
149	    const wm = makeDefaultWorkspaceManager();
150	    const fetched: string[] = [];
151	    const fetchFn = async (p: string) => { fetched.push(p); return makeStatus(); };
152	
153	    const mgr = new PollingManager(BASE_CONFIG, pm, wm, fetchFn);
154	    await mgr.refreshWorkspace('my-proj', 'STABLE');
155	
156	    assert.deepEqual(fetched.sort(), [
157	        '/fake/projects/my-proj/STABLE/repo-1',
158	        '/fake/projects/my-proj/STABLE/repo-2',
159	    ].sort());
160	});
161	
162	test('refreshWorkspace: updates the cache with the returned status', async () => {
163	    const project = {
164	        Id: 'p1',
165	        Repositories: ['r1'],
166	        Workspaces: { STABLE: {} },
167	    };
168	    const pm = makeProjectManager([project]);
169	    const wm = makeDefaultWorkspaceManager();
170	    const status1 = makeStatus('main');
171	    const status2 = makeStatus('dev');
172	
173	    let callCount = 0;
174	    const fetchFn = async (_: string) => callCount++ === 0 ? status1 : status2;
175	
176	    const mgr = new PollingManager(BASE_CONFIG, pm, wm, fetchFn);
177	
178	    await mgr.refreshWorkspace('p1', 'STABLE');
179	    assert.deepEqual(mgr.getStatus('/fake/projects/p1/STABLE/r1'), status1);
180	
181	    await mgr.refreshWorkspace('p1', 'STABLE');
182	    assert.deepEqual(mgr.getStatus('/fake/projects/p1/STABLE/r1'), status2);
183	});
