186	    const project = {
187	        Id: 'proj',
188	        Repositories: ['ok-repo', 'bad-repo'],
189	        Workspaces: { STABLE: {} },
190	    };
191	    const pm = makeProjectManager([project]);
192	    const wm = makeDefaultWorkspaceManager();
193	    const fetchFn = async (p: string) => {
194	        if (p.endsWith('bad-repo')) throw new Error('network error');
195	        return makeStatus();
196	    };
197	
198	    const mgr = new PollingManager(BASE_CONFIG, pm, wm, fetchFn);
199	    // Should not reject
200	    await assert.doesNotReject(() => mgr.refreshWorkspace('proj', 'STABLE'));
201	});
