207	        Workspaces: { STABLE: {} },
208	    };
209	    const pm = makeProjectManager([project]);
210	    const wm = makeDefaultWorkspaceManager();
211	    const okStatus = makeStatus('main');
212	    const fetchFn = async (p: string) => {
213	        if (p.endsWith('bad-repo')) throw new Error('fail');
214	        return okStatus;
215	    };
216	
217	    const mgr = new PollingManager(BASE_CONFIG, pm, wm, fetchFn);
218	    await mgr.refreshWorkspace('proj', 'STABLE');
